const form = force === 'auto'
  ? 'Choose the form that fits the content best (a diagram, a story, a set of figures or a poster).'
  : 'Use the ' + force + ' form; do not substitute another.';
const scenes = Math.max(0, Math.round(Number(req.SCENES) || 0));
const sceneLine = scenes > 0
  ? 'Render exactly ' + scenes + ' scenes, one item per scene, in the order the storyboard sets.'
  : '';
const hold = Math.max(0, Number(a.HOLD_SECONDS) || 0);
const holdLine = hold > 0
  ? 'End on a hold: the last frame stays still for at least ' + hold + ' seconds of the ' + seconds + '-second clip, so a reader can finish it. Give each scene the same hold at its end where the frame budget allows.'
  : '';
const reviewLine = 'Before rendering, review the layout. (1) Lay out with normal flow (flex or grid, padding, gaps) so every card and label sizes to its content and its text wraps - do NOT place text blocks at hand-computed left/top with a guessed width; that is what makes a label wider than its gap. (2) No two elements overlap: check each element full box including the right and bottom edges, and check a moving element at both the start and end of its motion. (3) No overflow: every text block fits its container with a margin on all four sides. (4) The first frame is clean: the runtime hides only class clip elements, so every other visible element (an SVG edge, a rail, decoration) needs its own opacity 0, because a gsap.fromTo that starts later leaves it visible at frame zero.';
