const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: Object.assign({}, base, { STATUS: 'RENDERED', CONTENT_TYPE: mime,
  IMAGE: 'data:' + mime + ';base64,' + buffer.toString('base64') }) }];

